import "core-js/modules/es7.array.includes";
import "core-js/modules/es6.string.includes";
import { dateFormat } from "@/util/date";
export default {
  name: 'template_tzdevice',
  props: ['formValue'],
  data: function data() {
    return {
      rules: {
        //校验规则
        disposeResult: [{
          required: true,
          message: '请选择处置结果',
          trigger: 'change'
        }]
      }
    };
  },
  computed: {
    czResults: function czResults(vm) {
      vm.formValue.disposeResult = '设备退运';
      return ['设备退运', '设备报修'];
    }
  },
  mounted: function mounted() {
    // console.log(444555, this.formValue)
  },
  methods: {
    validate: function validate(callback) {
      var _this = this;
      this.$refs.submitForm.validate(function (valid) {
        if (callback) {
          //告警处置时间 赋值
          if (valid) {
            _this.formValue.disposeTime = dateFormat(new Date());
          }
          callback(valid);
        }
      });
    },
    goWork: function goWork() {
      if (this.formValue.disposeResult.includes('退运')) {
        //详情 页面
        this.$router.push({
          path: '/detailRoute',
          query: {
            id: this.formValue.orderId,
            type: 'view',
            componentName: 'devReturnedAdd',
            routerTitle: '设备退运详情',
            formRouter: this.$route.fullPath
          }
        });
      }
      if (this.formValue.disposeResult.includes('报修')) {
        //新增 页面
        this.$router.push({
          path: '/detailRoute',
          query: {
            id: this.formValue.orderId,
            componentName: 'devRepairDetail',
            routerTitle: '设备报修详情',
            formRouter: this.$route.fullPath
          }
        });
      }
    }
  }
};
